CREATE TABLE "AiPolicyVersion" ("id" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"action" TEXT NOT NULL,"version" INTEGER NOT NULL,"policy" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"proposalId" TEXT,"createdById" TEXT NOT NULL,"approvedById" TEXT,"deployedById" TEXT,"rollbackOfId" TEXT,"shadowStartedAt" TIMESTAMP(3),"shadowEndedAt" TIMESTAMP(3),"deployedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiPolicyVersion_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "AiPolicyVersion_agencyId_action_version_key" ON "AiPolicyVersion"("agencyId","action","version");CREATE INDEX "AiPolicyVersion_agencyId_action_status_idx" ON "AiPolicyVersion"("agencyId","action","status");CREATE TABLE "AiPolicyShadowEvaluation" ("id" TEXT NOT NULL,"policyVersionId" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"sampleSize" INTEGER NOT NULL DEFAULT 0,"wouldAllow" INTEGER NOT NULL DEFAULT 0,"wouldBlock" INTEGER NOT NULL DEFAULT 0,"riskEvents" INTEGER NOT NULL DEFAULT 0,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiPolicyShadowEvaluation_pkey" PRIMARY KEY ("id"));CREATE INDEX "AiPolicyShadowEvaluation_policyVersionId_createdAt_idx" ON "AiPolicyShadowEvaluation"("policyVersionId","createdAt");